-- Transactional workspace aggregate and same-transaction relational projections.
-- The server owns writes; clients use tenant RLS for authorized reads.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE profiles(id uuid PRIMARY KEY, email text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workspaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, owner_id uuid NOT NULL REFERENCES profiles(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workspace_members(workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES profiles(id), role text NOT NULL CHECK(role IN ('owner','editor','viewer')), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,user_id));
CREATE INDEX workspace_members_user_idx ON workspace_members(user_id);
CREATE TABLE newsroom_state(workspace_id uuid PRIMARY KEY REFERENCES workspaces(id) ON DELETE CASCADE, data jsonb NOT NULL CHECK(jsonb_typeof(data)='object'), updated_at timestamptz NOT NULL DEFAULT now());
-- Vanilla Postgres development compatibility. Supabase already supplies auth.uid().
CREATE SCHEMA IF NOT EXISTS auth;
DO $outer$ BEGIN IF to_regprocedure('auth.uid()') IS NULL THEN
 EXECUTE $inner$CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $body$ SELECT nullif(current_setting('request.jwt.claim.sub',true),'')::uuid $body$ $inner$;
END IF; END $outer$;
CREATE OR REPLACE FUNCTION public.is_workspace_member(wid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=wid AND user_id=auth.uid()) $$;
REVOKE ALL ON FUNCTION public.is_workspace_member(uuid) FROM PUBLIC;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='authenticated') THEN CREATE ROLE authenticated NOLOGIN; END IF; END $$;
GRANT EXECUTE ON FUNCTION public.is_workspace_member(uuid) TO authenticated;
ALTER TABLE profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_self ON profiles FOR SELECT TO authenticated USING(id=auth.uid());
ALTER TABLE workspaces ENABLE ROW LEVEL SECURITY;
CREATE POLICY workspace_read ON workspaces FOR SELECT TO authenticated USING(is_workspace_member(id));
ALTER TABLE workspace_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY member_read ON workspace_members FOR SELECT TO authenticated USING(is_workspace_member(workspace_id));
ALTER TABLE newsroom_state ENABLE ROW LEVEL SECURITY;
-- No client policy for the aggregate: it includes encrypted credentials. Server only.
REVOKE ALL ON newsroom_state FROM PUBLIC, authenticated;
GRANT SELECT ON profiles,workspaces,workspace_members TO authenticated;
CREATE TABLE news_portals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, data jsonb NOT NULL CHECK(jsonb_typeof(data)='object'), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,id));
CREATE INDEX news_portals_workspace_idx ON news_portals(workspace_id,updated_at DESC);
ALTER TABLE news_portals ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_read ON news_portals FOR SELECT TO authenticated USING(is_workspace_member(workspace_id));
GRANT SELECT ON news_portals TO authenticated;
