ALTER TABLE portal_editions ADD COLUMN story_id uuid GENERATED ALWAYS AS ((data->>'storyId')::uuid) STORED;
ALTER TABLE portal_editions ADD COLUMN portal_id uuid GENERATED ALWAYS AS ((data->>'portalId')::uuid) STORED;
ALTER TABLE portal_editions ADD FOREIGN KEY(workspace_id,story_id) REFERENCES stories(workspace_id,id) DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE portal_editions ADD FOREIGN KEY(workspace_id,portal_id) REFERENCES news_portals(workspace_id,id) DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE published_posts ADD COLUMN edition_id uuid GENERATED ALWAYS AS ((data->>'editionId')::uuid) STORED;
ALTER TABLE published_posts ADD FOREIGN KEY(workspace_id,edition_id) REFERENCES portal_editions(workspace_id,id) DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE stories ADD COLUMN source_id uuid GENERATED ALWAYS AS ((data->>'sourceId')::uuid) STORED;
ALTER TABLE stories ADD FOREIGN KEY(workspace_id,source_id) REFERENCES sources(workspace_id,id) DEFERRABLE INITIALLY DEFERRED;
COMMENT ON TABLE newsroom_state IS 'Authoritative bounded workspace document. Server validates with Zod and updates relational projections in the same transaction. Split aggregates before large SaaS scale.';
